      background:
        linear-gradient(115deg, rgba(255,255,255,0.96) 0%, rgba(209,213,219,0.8) 22%, rgba(255,255,255,0.6) 42%, rgba(148,163,184,0.18) 58%, rgba(255,255,255,0.86) 76%, rgba(255,255,255,0.98) 100%);
      opacity: 0.74;
      filter: blur(14px);
      transform: translateX(-18%);
      transition: transform 700ms cubic-bezier(.2,.8,.2,1), opacity 700ms cubic-bezier(.2,.8,.2,1);
      z-index: -1;
    }.sc-tw .mercury:hover::before{
      transform: translateX(8%);
      opacity: 0.92;
    }.sc-tw .chip{
      transition: transform 260ms ease, background 260ms ease, box-shadow 260ms ease;
    }.sc-tw .chip:hover{
      transform: translateY(-1px);
    }.sc-tw .field{
      background: linear-gradient(180deg, rgba(255,255,255,0.92), rgba(248,250,252,0.78));
      box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.88),
        inset 0 -8px 18px rgba(148,163,184,0.08),
        0 10px 24px rgba(15,23,42,0.04);
    }.sc-tw .scroll-line{
      animation: drift linear both;
      animation-timeline: scroll(root);
    }

